def oob_error(data, B, train):
    n = len(data)
    votes = {i: [] for i in range(n)}
    for _ in range(B):
        idx = [randint(0, n - 1) for _ in range(n)]  # 복원추출
        model = train([data[i] for i in idx])
        inbag = set(idx)
        for i in range(n):
            if i not in inbag:  # 학습에 안 쓰인 표본만 평가
                votes[i].append(model.predict(data[i].x))
    wrong = total = 0
    for i, v in votes.items():
        if v:  # 한 번이라도 OOB였던 관측치
            total += 1
            wrong += majority(v) != data[i].y
    return wrong / total
